def sort_matrix(matrix: List[List[int]]) -> List[List[int]]:
    """
    Sort a matrix in ascending order according to the sum of its rows.

    Args:
        matrix: A list of lists representing a rectangular matrix where each sublist contains integers

    Returns:
        A new matrix with rows sorted by their sum in ascending order

    Raises:
        TypeError: If the input is not a list of lists or if any element in the matrix is not an integer
        ValueError: If the input is not a valid rectangular matrix
    """
    # Handle empty matrix
    if not matrix:
        return matrix

    # Validate input and check if rectangular
    if not isinstance(matrix, list) or not isinstance(matrix[0], list):
        raise TypeError("Input must be a list of lists")

    row_length = len(matrix[0])
    for i, row in enumerate(matrix):
        if not isinstance(row, list):
            raise TypeError("Input must be a list of lists")
        if len(row) != row_length:
            raise ValueError("Input must be a rectangular matrix")
        for j, element in enumerate(row):
            if not isinstance(element, int):
                raise TypeError(f"All elements must be integers, found {type(element).__name__} at position [{i}][{j}]")

    # Sort by row sum
    return sorted(matrix, key=sum)

